const Map<String, TranslatedGlossaryTerm> glossaryEn = {
  "Ácido": TranslatedGlossaryTerm(term: "Acid", definition: "A substance that donates protons (H⁺) or accepts electron pairs. In aqueous solution it generates hydronium ions and its pH is less than 7."),
  "Átomo": TranslatedGlossaryTerm(term: "Atom", definition: "The smallest unit of an element that keeps its chemical properties. It is made of protons, neutrons and electrons."),
  "Base": TranslatedGlossaryTerm(term: "Base", definition: "A substance that accepts protons (H⁺) or donates electron pairs. In aqueous solution it generates hydroxide ions and its pH is greater than 7."),
  "Catión": TranslatedGlossaryTerm(term: "Cation", definition: "An ion with a positive charge, formed when an atom loses electrons (for example, Na⁺, Ca²⁺)."),
  "Anión": TranslatedGlossaryTerm(term: "Anion", definition: "An ion with a negative charge, formed when an atom gains electrons (for example, Cl⁻, SO₄²⁻)."),
  "Mol": TranslatedGlossaryTerm(term: "Mole", definition: "An amount of substance containing 6.022×10²³ entities (atoms, molecules or ions): Avogadro's number."),
  "Molaridad": TranslatedGlossaryTerm(term: "Molarity", definition: "Concentration of a solution: moles of solute per liter of solution (mol/L)."),
  "pH": TranslatedGlossaryTerm(term: "pH", definition: "A measure of acidity: pH = −log[H₃O⁺]. Less than 7 is acidic, 7 is neutral and greater than 7 is basic."),
  "Equilibrio químico": TranslatedGlossaryTerm(term: "Chemical equilibrium", definition: "The state in which the rate of the forward reaction equals that of the reverse reaction and the concentrations stop changing."),
  "Constante de equilibrio (K)": TranslatedGlossaryTerm(term: "Equilibrium constant (K)", definition: "The ratio of the concentrations of products to reactants at equilibrium, each raised to its coefficient."),
  "Kps (producto de solubilidad)": TranslatedGlossaryTerm(term: "Ksp (solubility product)", definition: "The equilibrium constant for the dissolution of a sparingly soluble salt: the larger the Ksp, the more soluble the salt."),
  "Hidrólisis": TranslatedGlossaryTerm(term: "Hydrolysis", definition: "Reaction of an ion with water that changes the pH: salts of a weak acid and a strong base give basic solutions, and vice versa."),
  "Redox": TranslatedGlossaryTerm(term: "Redox", definition: "A reaction in which there is a transfer of electrons: one species is oxidized (loses them) and another is reduced (gains them)."),
  "Número de oxidación": TranslatedGlossaryTerm(term: "Oxidation number", definition: "The hypothetical charge an atom would have if all its bonds were ionic. It is used to follow the electrons in redox reactions."),
  "Electrón": TranslatedGlossaryTerm(term: "Electron", definition: "A subatomic particle with a negative charge that moves around the nucleus and takes part in chemical bonds."),
  "Electronegatividad": TranslatedGlossaryTerm(term: "Electronegativity", definition: "The ability of an atom to attract the electrons of a bond towards itself. Fluorine is the most electronegative."),
  "Configuración electrónica": TranslatedGlossaryTerm(term: "Electron configuration", definition: "The distribution of an atom's electrons in its levels and subshells (for example, [Ar] 3d⁷ 4s² for cobalt)."),
  "Isótopo": TranslatedGlossaryTerm(term: "Isotope", definition: "Atoms of the same element with a different number of neutrons (for example, ¹²C and ¹⁴C). They have the same Z and different mass."),
  "Enlace covalente": TranslatedGlossaryTerm(term: "Covalent bond", definition: "A bond between atoms that share pairs of electrons (for example, H₂, H₂O, CH₄)."),
  "Enlace iónico": TranslatedGlossaryTerm(term: "Ionic bond", definition: "A bond between ions of opposite charge by electrostatic attraction (for example, NaCl)."),
  "Enlace metálico": TranslatedGlossaryTerm(term: "Metallic bond", definition: "A bond between atoms of a metal, with delocalized electrons that form a “sea of electrons”."),
  "Hidrógeno (enlace de)": TranslatedGlossaryTerm(term: "Hydrogen bond", definition: "The attraction between a hydrogen attached to O, N or F and a lone pair on another atom. It explains why water is a liquid at room temperature."),
  "Fuerzas de Van der Waals": TranslatedGlossaryTerm(term: "Van der Waals forces", definition: "Weak attractions between molecules (dipole–dipole and London dispersion). They decide melting and boiling points."),
  "Grupo funcional": TranslatedGlossaryTerm(term: "Functional group", definition: "An atom or group of atoms that gives an organic molecule its characteristic properties (–OH, –COOH, –NH₂…)."),
  "Isómero": TranslatedGlossaryTerm(term: "Isomer", definition: "Compounds with the same molecular formula but a different structure or spatial arrangement."),
  "Quiralidad": TranslatedGlossaryTerm(term: "Chirality", definition: "The property of a molecule that cannot be superimposed on its mirror image, like the left and right hands."),
  "Enantiómero": TranslatedGlossaryTerm(term: "Enantiomer", definition: "Each of the two chiral stereoisomers that are mirror images of each other."),
  "Catálisis": TranslatedGlossaryTerm(term: "Catalysis", definition: "The increase in the rate of a reaction by a catalyst, which is not consumed in the reaction."),
  "Energía de activación": TranslatedGlossaryTerm(term: "Activation energy", definition: "The minimum energy molecules must have for a collision to produce a reaction."),
  "Entalpía (ΔH)": TranslatedGlossaryTerm(term: "Enthalpy (ΔH)", definition: "Heat exchanged at constant pressure. ΔH < 0 is exothermic (releases heat); ΔH > 0 is endothermic (absorbs heat)."),
  "Entropía (ΔS)": TranslatedGlossaryTerm(term: "Entropy (ΔS)", definition: "A measure of the disorder of a system. Spontaneous processes tend to increase the entropy of the universe."),
  "Energía libre de Gibbs (ΔG)": TranslatedGlossaryTerm(term: "Gibbs free energy (ΔG)", definition: "ΔG = ΔH − TΔS. If ΔG < 0, the process is spontaneous; if ΔG > 0, it is not."),
  "Valoración": TranslatedGlossaryTerm(term: "Titration", definition: "A technique for determining the concentration of a solution by adding, little by little, another of known concentration until the equivalence point."),
  "Punto de equivalencia": TranslatedGlossaryTerm(term: "Equivalence point", definition: "The moment in a titration when the amount added is exactly what is needed to react completely with the sample."),
  "Indicador": TranslatedGlossaryTerm(term: "Indicator", definition: "A substance that changes color over a pH range and lets you see the end point of a titration (for example, phenolphthalein)."),
  "Soluto": TranslatedGlossaryTerm(term: "Solute", definition: "The substance that dissolves in a solvent to form a solution."),
  "Disolvente": TranslatedGlossaryTerm(term: "Solvent", definition: "The substance that dissolves the solute; in aqueous solutions it is water."),
  "Disolución saturada": TranslatedGlossaryTerm(term: "Saturated solution", definition: "A solution containing the maximum amount of solute that can dissolve at that temperature."),
  "Precipitado": TranslatedGlossaryTerm(term: "Precipitate", definition: "An insoluble solid that forms in a solution during a chemical reaction."),
  "Ácido poliprótico": TranslatedGlossaryTerm(term: "Polyprotic acid", definition: "An acid that can donate more than one proton per molecule (for example, H₂SO₄, H₃PO₄), in successive steps."),
  "Anfótero": TranslatedGlossaryTerm(term: "Amphoteric", definition: "A substance that can act as an acid or as a base depending on what it reacts with (for example, water, Al(OH)₃)."),
  "Metal de transición": TranslatedGlossaryTerm(term: "Transition metal", definition: "An element of the d block of the periodic table, with several oxidation states and often colored compounds."),
  "Serie de actividad": TranslatedGlossaryTerm(term: "Activity series", definition: "The order of metals by how easily they lose electrons and react. A metal displaces those below it."),
  "Orbital": TranslatedGlossaryTerm(term: "Orbital", definition: "A region of space where there is a high probability of finding an electron. The s, p, d and f orbitals have different shapes."),
  "Regla del octeto": TranslatedGlossaryTerm(term: "Octet rule", definition: "The tendency of atoms to have 8 electrons in their valence shell when forming bonds, like the noble gases."),
  "Polaridad": TranslatedGlossaryTerm(term: "Polarity", definition: "The uneven distribution of charge in a molecule, due to electronegativity differences between its atoms."),
  "Tensión superficial": TranslatedGlossaryTerm(term: "Surface tension", definition: "The force that holds the surface of a liquid together; that is why some insects walk on water."),
  "Presión parcial": TranslatedGlossaryTerm(term: "Partial pressure", definition: "The pressure a gas in a mixture would exert if it alone occupied the whole volume (Dalton's law)."),
  "Volumen molar": TranslatedGlossaryTerm(term: "Molar volume", definition: "The volume occupied by one mole of gas: 22.4 L under standard conditions (0 °C and 1 atm); 24.8 L at SATP (25 °C and 1 atm)."),
  "Reactivo limitante": TranslatedGlossaryTerm(term: "Limiting reactant", definition: "The reactant that runs out first in a reaction and determines the maximum amount of product that can form."),
  "Rendimiento": TranslatedGlossaryTerm(term: "Yield", definition: "The percentage of the theoretical product actually obtained in a reaction. It never exceeds 100 %."),
};

